from pathlib import Path
import base64,gzip
FILES={
 "site/index.html":"",
 "site/styles.css":"",
 "site/app.js":""
}
for path,b64 in FILES.items():
 p=Path(path);p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(gzip.decompress(base64.b64decode(b64)));print("generated",path,p.stat().st_size)
